import json
from pathlib import Path
subject = 'site:sqlite-join-exercise'
digest = '52081bc87c5221b41e2b4a65703a3ce5a6b01ec763ef30a179b2fcb99481e981'
pages = sorted(Path('world/pages').glob('reviews-*.json'))
def records(value):
    if isinstance(value, dict):
        if value.get('subject') == subject and value.get('digest') == digest:
            yield {key: value.get(key) for key in ('seq', 'verdict', 'host_provider', 'host_turn')}
        for child in value.values():
            yield from records(child)
    elif isinstance(value, list):
        for child in value:
            yield from records(child)
reviews = [record for page in pages for record in records(json.loads(page.read_text()))]
print(json.dumps({'subject': subject, 'digest': digest, 'pages_read': [str(page) for page in pages], 'matching_reviews': reviews, 'coverage': 'Provided review pages only. Host determines provider independence and deployment eligibility.'}, indent=2))
